// Some portions generated by Codex
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');
const scripts = require('./workbench-scripts.js').compiledScriptsDir();

function flatten(template) {
    if (Array.isArray(template)) return template.map(flatten).join('');
    if (template && Array.isArray(template.strings)) {
        return template.strings.map((value, index) => value + flatten(template.values[index])).join('');
    }
    return template === null || template === undefined ? '' : String(template);
}

function renderFooter(basePath) {
    const workbench = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const window = {};
    const context = vm.createContext({ console, URL, URLSearchParams, Promise, window, workbench, setTimeout });
    for (const file of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        vm.runInContext(fs.readFileSync(path.join(scripts, file), 'utf8'), context, { filename: file });
    }
    window.workbench = context.workbench;
    const runtime = { html(strings, ...values) { return { strings: Array.from(strings), values }; }, nothing: '' };
    const markup = flatten(workbench.views.pageTemplate({ viewId: 'information', vars: [], rows: [], metadata: {} },
        { basePath, repositoryId: 'SYSTEM', workbench: {} }, runtime));
    return markup.slice(markup.indexOf('id="footer"'));
}

for (const basePath of ['/rdf4j-workbench', '/custom/nested/workbench', '']) {
    test('legal footer links to this installation at ' + (basePath || '/'), () => {
        const footer = renderFooter(basePath);
        assert.match(footer, /Copyright © Eclipse RDF4J contributors/);
        for (const file of ['NOTICE.md', 'edl-v1.0.txt', 'third-party-notices.html']) {
            assert.ok(footer.includes(basePath + '/legal/' + file), file + ' must use the deployed context');
        }
        assert.match(footer, /Project notice/);
        assert.match(footer, /License/);
        assert.match(footer, /Third-party notices/);
        assert.ok(!footer.includes('github.com'), 'installed notices must not drift with a remote branch');
    });
}
